import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Agent Loops Clearly Explained","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-10-@startupideaspod-064018.md","filePath":"research/tweets/2026-06-10-@startupideaspod-064018.md","lastUpdated":1785909234000}'),i={name:"research/tweets/2026-06-10-@startupideaspod-064018.md"};function s(h,e,l,n,p,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-loops-clearly-explained" tabindex="-1">Agent Loops Clearly Explained <a class="header-anchor" href="#agent-loops-clearly-explained" aria-label="Permalink to &quot;Agent Loops Clearly Explained&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/startupideaspod/status/2064517118453064018" target="_blank" rel="noreferrer">@startupideaspod</a>（The Startup Ideas Podcast (SIP) 🧃）<br><strong>日期</strong>：2026-06-10<br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 95 · 🔁 13 · 👁 5288 · 🔖 159</p><hr><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Agent Loop 反向視角：Loop 僅適合有明確二元標準的任務（code review），app 建構因 spec 永遠不完整而必然偏移；Code review loop（Greptile score≥4, max 5 retry, ≤1000 lines）是唯一值得複製的模式；「Human in the loop is the best loop」。</p><hr><h2 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h2><ol><li>Human-in-the-loop vs 完全自動 loop：前者你主導，後者你放棄中間的控制點</li><li>Loop 炒作者大多在大型實驗室，享有無限 token 預算，對一般訂閱用戶不適用</li><li>唯一值得的 loop：Code review loop（Greptile → score/5 → 低於 4 重試 → 最多 5 次）</li><li>Loop 成功條件：固定、二元、可定義的 target（pass/fail），無需創意或願景判斷</li><li>App 建構不適合 loop：spec 永遠不完整，agent 填補空白只會填出錯誤假設</li></ol><hr><h2 id="關鍵數據-工具-引用" tabindex="-1">關鍵數據 / 工具 / 引用 <a class="header-anchor" href="#關鍵數據-工具-引用" aria-label="Permalink to &quot;關鍵數據 / 工具 / 引用&quot;">​</a></h2><ul><li>Code review loop：Greptile，分數≥4 可上線，max 5 retry，每次 push ≤1000 lines</li><li>Skill 名稱：「grep loop」</li><li>Podcast：Startup Ideas Podcast，主持 Greg + 教授 Ross Mike</li><li>引用 loop 模式：Ralph Loops、Ralph Wiggum、Slash Goal</li></ul><hr><h2 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h2><ol><li>&quot;Human in the loop is the best loop&quot; 過於絕對，忽略了有清晰規格的自動化場景</li><li>Greptile 數值評分（4/5 門檻）可能因 code 風格/規模產生假陽性</li><li>1000 行上限是經驗法則，缺乏理論依據</li></ol><hr><h2 id="_5-維度評分" tabindex="-1">5 維度評分 <a class="header-anchor" href="#_5-維度評分" aria-label="Permalink to &quot;5 維度評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7</td><td>Code review loop 模式可直接複製</td></tr><tr><td>B. 創新性 (20%)</td><td>7</td><td>二元標準 vs 創意標準分類有洞見</td></tr><tr><td>C. 證據品質 (20%)</td><td>7</td><td>Podcast 訪談 + 具體 guardrail</td></tr><tr><td>D. 技術深度 (15%)</td><td>6</td><td>概念清晰，程式細節薄</td></tr><tr><td>E. 泛化性 (15%)</td><td>8</td><td>AI builder loop 決策框架</td></tr></tbody></table><p><strong>加權總分：7.0 → Rule</strong></p><hr><h2 id="整合決策" tabindex="-1">整合決策 <a class="header-anchor" href="#整合決策" aria-label="Permalink to &quot;整合決策&quot;">​</a></h2><p><strong>Rule</strong> — Loop 適用範圍判斷規則：二元標準任務（code review）適合 loop，創意/願景任務保留 human-in-the-loop</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>The loudest voices in AI have a new flex: they don&#39;t write prompts anymore, they build agentic loops. On the Startup Ideas Podcast, host Greg brought on Professor Ross Mike to settle whether that&#39;s the future of building or an expensive trap.</p><p>The short answer: for almost anyone building a real app, it&#39;s a money fire. The longer answer matters, because there is exactly one place a loop earns its keep.</p><h2 id="first-two-ways-to-work-with-an-ai-agent" tabindex="-1">First, Two Ways to Work With an AI Agent <a class="header-anchor" href="#first-two-ways-to-work-with-an-ai-agent" aria-label="Permalink to &quot;First, Two Ways to Work With an AI Agent&quot;">​</a></h2><p>Most of us already use one of them every day.</p><p>Human in the loop. You prompt the agent. You read the result, you test it, you decide the next move. The agent builds. You direct, you govern, you approve. This is how people use Cursor, Claude, and Codex right now.</p><p>Build the landing page. Check it. Then move to auth. Then the backend. One step, one review, then the next.</p><h2 id="the-loop-everyone-is-hyping" tabindex="-1">The Loop Everyone Is Hyping <a class="header-anchor" href="#the-loop-everyone-is-hyping" aria-label="Permalink to &quot;The Loop Everyone Is Hyping&quot;">​</a></h2><p>The new trend removes you from the middle.</p><p>You write a single spec file, a prd.md task list that holds everything the agent should build. You fire the loop one time. Then you walk away.</p><p>From there the agent generates a result, feeds that result back to itself, and keeps building with no check-ins. It sounds like the future. It might even be the future. The problem is what happens between &quot;go&quot; and &quot;done.&quot;</p><h2 id="picture-the-developer-who-never-checks-in" tabindex="-1">Picture the Developer Who Never Checks In <a class="header-anchor" href="#picture-the-developer-who-never-checks-in" aria-label="Permalink to &quot;Picture the Developer Who Never Checks In&quot;">​</a></h2><p>Here&#39;s the analogy that makes it click.</p><p>You hire a brilliant developer. You hand over the spec and they vanish, then return with a &quot;finished&quot; product. To get there, they made a stack of assumptions about look, feel, and architecture.</p><p>Most of those assumptions miss your vision. Now you own a finished build that points the wrong way.</p><p>Your spec felt complete. It never is. There&#39;s always an edge case, always a detail the document skipped. Hand an agent that gap and it fills it with guesses. Wrong guesses. Expensive guesses.</p><h2 id="the-hype-comes-from-people-with-free-tokens" tabindex="-1">The Hype Comes From People With Free Tokens <a class="header-anchor" href="#the-hype-comes-from-people-with-free-tokens" aria-label="Permalink to &quot;The Hype Comes From People With Free Tokens&quot;">​</a></h2><p>This part is the quiet truth of the whole debate.</p><p>The people championing open loops work at the big labs. They have unlimited model access and no token budget. If your tokens were free, you would loop everything too.</p><p>On a $20 or $100 subscription, an open loop burns through your balance fast. Great for research and experiments. Rough for a wallet that has a limit.</p><p>You&#39;ve seen the names: Ralph Loops, Ralph Wiggum, Slash Goal. Slash goal, slash loop, whatever your tool calls it. Same machine. Perfect for a throwaway prototype, a catastrophe for the app you actually care about.</p><h2 id="the-one-loop-worth-copying-code-review" tabindex="-1">The One Loop Worth Copying: Code Review <a class="header-anchor" href="#the-one-loop-worth-copying-code-review" aria-label="Permalink to &quot;The One Loop Worth Copying: Code Review&quot;">​</a></h2><p>The professor runs exactly one loop, and it&#39;s worth stealing.</p><p>Every feature he pushes to GitHub gets checked by a code-review agent. He uses Greptile, which returns a score out of 5. His rule is simple: nothing ships to production below a 4.</p><p>He built a small skill called &quot;grep loop.&quot; It tells the agent to read the GitHub review, fix what it flagged, push again, and wait for the new score. A low score restarts the cycle. The loop stops at a 5, or it quits after 5 tries.</p><h2 id="why-this-loop-works-when-app-loops-fail" tabindex="-1">Why This Loop Works When App Loops Fail <a class="header-anchor" href="#why-this-loop-works-when-app-loops-fail" aria-label="Permalink to &quot;Why This Loop Works When App Loops Fail&quot;">​</a></h2><p>The difference is the feedback signal.</p><p>Code review has a fixed, defined target. The output is binary: the code passed or it didn&#39;t. There&#39;s no creativity to invent and no vision to guess at.</p><p>Building an app is the opposite. You can&#39;t fully picture the thing yet, so you can&#39;t hand an agent a clean target to chase. That&#39;s why a loop on a startup build drifts, while a loop on code review converges.</p><h2 id="even-the-good-loop-has-a-ceiling" tabindex="-1">Even the Good Loop Has a Ceiling <a class="header-anchor" href="#even-the-good-loop-has-a-ceiling" aria-label="Permalink to &quot;Even the Good Loop Has a Ceiling&quot;">​</a></h2><p>Honesty from the episode: this loop breaks too.</p><p>Push more than 1,000 lines at once and the agent can almost never reach a 5. There&#39;s too much code to hold in context and review well. So he caps each push at 1k lines, or tells Cursor to split the work into smaller PRs.</p><p>A reliable loop still needs guardrails. Even the clean ones have a size where they fall apart.</p><h2 id="what-an-open-loop-forgets-feedback" tabindex="-1">What an Open Loop Forgets: Feedback <a class="header-anchor" href="#what-an-open-loop-forgets-feedback" aria-label="Permalink to &quot;What an Open Loop Forgets: Feedback&quot;">​</a></h2><p>This is the piece the hype skips entirely.</p><p>When you build a startup, you have to put the product in front of real people and react to what they say. An open build-loop never stops to do that. It presses &quot;go&quot; and removes the off-ramp.</p><p>Think of full self-driving from Miami to Charleston. You spot a great diner and crave the fried chicken sandwich. Too late. The train left the station. Building needs the exits. Loops pave right over them.</p><h2 id="the-verdict" tabindex="-1">The Verdict <a class="header-anchor" href="#the-verdict" aria-label="Permalink to &quot;The Verdict&quot;">​</a></h2><p>Loops fit confined, binary work. Code review. Bulk SEO pages built off a fixed formula. Anything where the output is black or white with no taste involved.</p><p>Anything that needs creativity, you steer yourself. Will full agentic loops arrive someday? Yes, the episode gives them full credit for that. Today, on a real budget, the math falls apart.</p><p>So before you hand an agent the wheel and walk away, keep the line that closed the show:</p><p>Human in the loop is the best loop.</p><p>Checkout the full episode:</p><p>Apple: <a href="https://podcasts.apple.com/us/podcast/the-startup-ideas-podcast/id1593424985?i=1000771935799" target="_blank" rel="noreferrer">https://podcasts.apple.com/us/podcast/the-startup-ideas-podcast/id1593424985?i=1000771935799</a></p><p>Spotify: <a href="https://open.spotify.com/episode/2diPwvX475jhlYOjjt2QeV?si=7c24506bf2124456" target="_blank" rel="noreferrer">https://open.spotify.com/episode/2diPwvX475jhlYOjjt2QeV?si=7c24506bf2124456</a></p><p>Youtube: <a href="https://www.youtube.com/watch?v=7clJ8IH784Q" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=7clJ8IH784Q</a></p>',68)])])}const g=t(i,[["render",s]]);export{c as __pageData,g as default};
